PREFIX brick: <http://brickschema.org/schema/Brick#>
PREFIX ref: <https://brickschema.org/0.1/core/term/term#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT ?node ?label ?ts WHERE {
  ?node rdfs:label "Perimeter_bot_ZN_4" .
  OPTIONAL { ?node ref:hasTimeseriesId ?ts . }
}

PREFIX brick: <http://brickschema.org/schema/Brick#>
PREFIX ref: <https://brickschema.org/0.1/core/term/term#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT ?zone ?zlabel ?point ?pclass ?ts WHERE {
  ?zone rdfs:label "Perimeter_bot_ZN_4" .
  ?zone brick:hasPoint ?point .
  OPTIONAL { ?point rdf:type ?pclass . }
  OPTIONAL { ?point ref:hasTimeseriesId ?ts . }
  FILTER (str(?pointClass) != "" || 1=1)
}

